//! `docs/configuration.md`, rendered from the `gitterrace-config` key table. The descriptions are
//! the doc comments on the settings, so the page cannot drift from the loader.

use std::fmt::Write as _;

use crate::out::Out;

const PATH: &str = "docs/configuration.md";

pub fn render() -> Out {
    let mut s = String::from(
        "<!-- Generated by `cargo xtask generate`. Do not edit. -->\n\n# Configuration\n\n\
         One optional file, `config.toml`, in `$XDG_CONFIG_HOME/gitterrace` or \
         `~/.config/gitterrace` (`--config DIR` picks another folder). It is never read from a \
         served repository. A flag beats the file, the file beats the default. Unknown keys \
         warn, invalid values stop startup naming the key. `git terrace config` prints what is \
         in force and where each value came from.\n\n\
         A running server reloads `config.toml` within a second of an edit. An invalid edit is \
         logged with the key and the old settings stay. Open pages show \"Updated, refresh\". \
         Settings marked \"Needs a restart\" log a warning and keep their running value.\n\n\
         Per-repository overrides go under `[repo.NAME]` (the repository's folder name) and \
         take `exclude`, a list of path globs added to `insights.exclude`. \
         `[repo.NAME.features]` turns a feature off for that repository only, with the keys of \
         `[features]` set to `false`. It never turns one on, and the server-wide ones \
         (`repo_admin_enabled`, `settings_enabled`, `picker_enabled`, `credit_enabled`, \
         `api_enabled`) are refused there.\n\n\
         A feature that shows this machine or changes it (working tree, live updates, actions, \
         adding repositories, the settings page) stays off on a public server whatever \
         `[features]` says: the file can \
         turn a feature off, never past what `--public` or the loopback check allows.\n\n\
         Actions live in their own file, `actions.toml`, because they run commands.\n",
    );
    s.push_str("\n## Names\n\nOne rule for every key and flag, from `gitterrace_config::naming`. A renamed key gets no alias: the old name warns as unknown and the default applies.\n\n");
    s.push_str(&gitterrace_config::naming::doc_table());
    let mut section = "";
    for k in gitterrace_config::keys() {
        if k.section != section {
            section = k.section;
            let _ = write!(
                s,
                "\n## `[{section}]`\n\n| Key | Type | Default | Description |\n| --- | --- | --- | --- |\n"
            );
        }
        let mut doc = k.doc.split_whitespace().collect::<Vec<_>>().join(" ");
        if k.section == "resources" && k.name == "cache_mb" {
            // The shares come from the code's table, so the page cannot go stale.
            doc = doc.replacen(
                "between the caches.",
                &format!("between the caches. {}", gitterrace_config::shares_doc()),
                1,
            );
        }
        let _ = writeln!(s, "| `{}` | {} | `{}` | {} |", k.name, k.ty, k.default, doc);
    }
    Out::file(PATH, s)
}

#[cfg(test)]
mod tests {
    use super::render;
    use crate::out::Out;

    /// The page's rows, the settings form and the schema list the same keys in the same order,
    /// so a key the form leaves out (or the page) goes red here.
    #[test]
    fn page_rows_equal_form_field_ids() {
        let Out::File { body, .. } = render() else {
            panic!("the configuration page is a whole file")
        };
        let mut rows = Vec::new();
        let mut section = "";
        for line in body.lines() {
            if let Some(s) = line
                .strip_prefix("## `[")
                .and_then(|s| s.strip_suffix("]`"))
            {
                section = s;
            } else if let Some(name) = line.strip_prefix("| `").and_then(|l| l.split('`').next())
                && !section.is_empty()
            {
                rows.push(format!("{section}.{name}"));
            }
        }
        let loaded = gitterrace_config::parse("").expect("empty config");
        let form: Vec<String> = gitterrace_config::fields(&loaded)
            .iter()
            .map(|f| f.id.to_owned())
            .collect();
        assert_eq!(rows, form);
    }
}
